<script setup>
import { ref, computed, onMounted, onUnmounted, nextTick } from 'vue'
import { getCharacters } from '@/services/firebase'
import AppIcon from '@/components/AppIcon.vue'
const tiers = ['Semua', 'Pandawa', 'Kurawa', 'Punakawan']
const selectedTier = ref('Semua'), query = ref(''), characters = ref([]), selectedCharacter = ref(null), loading = ref(true), error = ref(''), dialog = ref(null)
let disposed = false, previousOverflow = '', opener = null
const filteredCharacters = computed(() => characters.value.filter(char => (selectedTier.value === 'Semua' || char.tier === selectedTier.value) && `${char.name} ${char.aliases.join(' ')}`.toLowerCase().includes(query.value.toLowerCase())))
async function loadData() { try { const data = await getCharacters(); if (!disposed) characters.value = data } catch { error.value = 'Katalog belum dapat dimuat. Coba muat ulang halaman.' } finally { loading.value = false } }
function imageError(event) { event.target.onerror = null; event.target.src = '/brand-mark.webp'; event.target.classList.add('image-fallback') }
async function openDetail(character) {
 opener = document.activeElement; previousOverflow = document.body.style.overflow
 selectedCharacter.value = character; document.body.style.overflow = 'hidden'
 await nextTick(); dialog.value?.showModal?.()
}
function closeDetail() { dialog.value?.close?.(); selectedCharacter.value = null; document.body.style.overflow = previousOverflow; opener?.focus() }
onMounted(loadData)
onUnmounted(() => { disposed = true; if (selectedCharacter.value) { dialog.value?.close?.(); document.body.style.overflow = previousOverflow } })
</script>
<template><section>
 <div class="page-heading"><p class="eyebrow">ENSIKLOPEDIA WAYANG KULIT</p><h1>Nama, watak,<br /><span>dan kisah di baliknya.</span></h1><p>Jelajahi {{ characters.length || 'koleksi' }} tokoh dalam katalog lokal. Pandawa, Kurawa, dan Punakawan—masing-masing membawa cerita yang berbeda.</p></div>
 <div class="catalog-toolbar"><div class="catalog-filters" role="group" aria-label="Golongan tokoh"><button v-for="tier in tiers" :key="tier" class="button" :class="{ selected: selectedTier === tier }" :aria-pressed="selectedTier === tier" @click="selectedTier = tier">{{ tier }}</button></div><label class="catalog-search"><AppIcon name="search" /><input v-model="query" class="input" placeholder="Cari tokoh atau alias…" aria-label="Cari tokoh atau alias" /></label></div>
 <div v-if="error" class="notice" role="status">{{ error }}</div><div v-if="loading" class="catalog-grid"><div v-for="index in 8" :key="index" class="skeleton h-80 rounded-xl" /></div><p v-else-if="!filteredCharacters.length" class="empty-state">Tidak ada tokoh yang sesuai. Coba kata kunci atau golongan lain.</p>
 <section v-else class="catalog-grid" aria-label="Koleksi tokoh"><article v-for="character in filteredCharacters" :key="character.id" class="catalog-card" @click="openDetail(character)"><button :aria-label="`Baca kisah ${character.name}`" class="catalog-card-button"><div class="catalog-image"><img :src="character.imageUrl" :alt="character.name" loading="lazy" width="300" height="360" @error="imageError" /><span class="catalog-tier">{{ character.tier }}</span></div><div class="catalog-copy"><h2>{{ character.name }}<AppIcon name="arrow" /></h2><p>{{ character.aliases.slice(0,2).join(' / ') }}</p></div></button></article></section>
 <Teleport to="body"><dialog v-if="selectedCharacter" ref="dialog" class="character-dialog" aria-labelledby="character-title" @cancel.prevent="closeDetail" @click="($event) => { if ($event.target === dialog) closeDetail() }"><div class="character-detail"><button class="icon-button detail-close" aria-label="Tutup kisah tokoh" @click="closeDetail"><AppIcon name="close" /></button><div class="detail-image"><img :src="selectedCharacter.imageUrl" :alt="selectedCharacter.name" @error="imageError" /></div><div class="detail-copy"><p class="eyebrow">{{ selectedCharacter.tier }}</p><h2 id="character-title">{{ selectedCharacter.name }}</h2><p class="detail-alias">{{ selectedCharacter.aliases.join(' · ') }}</p><dl><div><dt>Senjata</dt><dd>{{ selectedCharacter.weapon }}</dd></div><div><dt>Watak</dt><dd>{{ selectedCharacter.temperament }}</dd></div><div><dt>Keluarga</dt><dd>{{ selectedCharacter.family.father }} / {{ selectedCharacter.family.mother }}</dd></div></dl><p class="detail-story">{{ selectedCharacter.description }}</p></div></div></dialog></Teleport>
</section></template>
