ute; top: 12px; right: 12px; background: var(--panel); z-index: 1; border: 1px solid var(--line); }.detail-image { display: flex; background: #d7ba89; }.detail-image img { width: 100%; object-fit: cover; }.detail-copy { padding: 38px; }.detail-copy h2 { font-size: 34px; margin-top: 14px; }.detail-alias { color: var(--muted); font-size: 11px; margin: 8px 0 24px; }.detail-copy dl > div { padding: 12px 0; border-top: 1px solid var(--line); }.detail-copy dt { font-size: 10px; color: var(--brass); text-transform: uppercase; letter-spacing: .1em; }.detail-copy dd { font-size: 12px; margin-top: 6px; }.detail-story { line-height: 1.9; font-size: 13px; color: var(--muted); margin-top: 24px; }.image-fallback { object-fit: contain !important; padding: 40px; }
@media(max-width:1279px) { .catalog-grid { grid-template-columns: repeat(3,minmax(0,1fr)); } }@media(max-width:767px) { .catalog-grid { grid-template-columns: repeat(2,minmax(0,1fr)); gap: 12px; }.catalog-copy { padding: 14px; }.catalog-copy h2 { font-size: 17px; }.character-detail { grid-template-columns: 1fr; }.detail-image img { max-height: 280px; object-fit: contain; }.detail-copy { padding: 24px; }.catalog-search { width: 100%; } }
</style>
